const CACHE_NAME="copilot-remote-v1",SHELL=["/","/index.html"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(SHELL)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE_NAME).map(e=>caches.delete(e)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{e.request.url.includes("trycloudflare.com")||e.request.url.includes("ws://")||e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)))}),self.addEventListener("push",e=>{const t=e.data?.json()??{};e.waitUntil(clients.matchAll({type:"window",includeUncontrolled:!0}).then(e=>{if(!e.some(e=>"visible"===e.visibilityState))return self.registration.showNotification(t.title??"Copilot Remote",{body:t.body??"",icon:"/icon-192.png",badge:"/icon-192.png",tag:"copilot-remote",renotify:!0,data:{url:t.url??"/"}})}))}),self.addEventListener("notificationclick",e=>{e.notification.close(),e.waitUntil(clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{const i=t.find(e=>e.url.includes(self.location.origin));return i?i.focus():clients.openWindow(e.notification.data?.url??"/")}))});